 for(unsigned track=1;track<16;++track)p->tracks[track].instrument=Instrument::DaisyAnalogDrums;
 MidiImport drop(fs);CHECK(drop.start("gm.mid",*p,0,0));while(drop.busy())drop.service();CHECK(drop.done() && drop.dropped()==1);
 // Audio-less kits still send GM notes and release precisely on physical release.
 CHECK(e->stage_project(*p));e->render(frame,0);midi(*e,0x90);Command hit{CommandType::Trigger,0,1,100};hit.parameter=4;hit.scalar=12;CHECK(e->submit(hit));e->render(frame,1);CHECK(midi(*e,0x90)==std::vector<unsigned>{38});Command off{CommandType::NoteOff,0,12,1};off.parameter=4;CHECK(e->submit(off));e->render(frame,1);CHECK(midi(*e,0x80)==std::vector<unsigned>{38});
 ui->project_loaded();CHECK(ui->arm_note_record(true) && ui->play());e->render(frame,1);ui->poll();midi(*e,0x90);Command incoming{CommandType::MidiInput,0,42,0x90};incoming.scalar=90;CHECK(e->submit(incoming));e->render(frame,1);ui->poll();CHECK(track_at(*p,0,0).kit.steps[2][0].enabled);CHECK(midi(*e,0x90).empty());
 ChunkBuffer encoded;CHECK(encode_project_buffer(encoded,*p));auto decoded=std::make_unique<ProjectState>();ChunkSource source{encoded.data,encoded.size,0};CHECK(decode_project(source,*decoded));CHECK(track_at(*decoded,0,0).kit.pads[1].gm_note==38);
