static void soundfont(){DesktopFiles fs;CHECK(fs.write("fixture.sf2",0,kSoundFontFixture,sizeof kSoundFontFixture,true));SoundFontCache cache;WavView bank;CHECK(cache.load(fs,"fixture.sf2",bank));SoundFontVoice pad,gm,melody;pad.init(0,48000);gm.init(1,48000);melody.init(2,48000);SoundFontState drums,normal;drums.values[0]=128;drums.values[1]=10;auto hz=[](unsigned note){return 440*powf(2,float(int(note)-69)/12);};CHECK(pad.trigger(bank.soundfont,hz(37),100,drums));CHECK(gm.trigger(bank.soundfont,hz(38),100,normal));CHECK(melody.trigger(bank.soundfont,hz(37),100,normal));double diff=0,diff_melody=0,energy=0;for(unsigned i=0;i<2048;++i){float a,b,c,d,l,r;pad.next(hz(37),true,a,b);gm.next(hz(38),true,c,d);melody.next(hz(37),true,l,r);diff+=fabs(a-c)+fabs(b-d);diff_melody+=fabs(a-l)+fabs(b-r);energy+=a*a+b*b;}CHECK(energy>.001 && diff<.01 && diff_melody>.1);double bend_difference=0;for(unsigned i=0;i<512;++i){float a,b,c,d;pad.next(hz(38),true,a,b);gm.next(hz(39),true,c,d);bend_difference+=fabs(a-c)+fabs(b-d);}CHECK(bend_difference<.02);CHECK(pad.trigger(bank.soundfont,hz(38),100,drums,true,37));CHECK(gm.trigger(bank.soundfont,hz(39),100,normal,false,38));CHECK(pad.key()==38);double initial_bend_difference=0;for(unsigned i=0;i<512;++i){float a,b,c,d;pad.next(hz(38),true,a,b);gm.next(hz(39),true,c,d);initial_bend_difference+=fabs(a-c)+fabs(b-d);}CHECK(initial_bend_difference<.02);}
