static void smf_files(){
 DesktopFiles fs;auto p=std::make_unique<ProjectState>();make_empty_project(*p);p->tracks[0].instrument=Instrument::ExternalMidi;auto bytes=score({60,61,62,63,64,65,66,67});CHECK(fs.write("eight.mid",0,bytes.data(),unsigned(bytes.size()),true));MidiImport melody(fs);CHECK(melody.start("eight.mid",*p,0,0));while(melody.busy())melody.service();CHECK(melody.done() && melody.notes()==8 && melody.result().steps[0].chord[6]==67 && melody.result().steps[0].native_drum);
 p->tracks[0].instrument=Instrument::DrumKit;auto e=std::make_unique<Engine>(8000);CHECK(e->stage_project(*p));float audio[128]{};e->render(audio,0);MidiCapture output(fs,*e);CHECK(output.start("exports",true));e->render(audio,0);output.service();Command hit{CommandType::Trigger,0,1,100};hit.parameter=4;hit.scalar=12;CHECK(e->submit(hit));e->render(audio,64);output.service();Command off{CommandType::NoteOff,0,12,1};off.parameter=4;CHECK(e->submit(off));e->render(audio,64);output.service();CHECK(output.stop());e->render(audio,0);for(unsigned i=0;i<100 && output.busy();++i)output.service();CHECK(output.state()==MidiCapture::State::Idle);MidiImport drum(fs);CHECK(drum.start(output.path(),*p,0,0));while(drum.busy())drum.service();CHECK(drum.done() && drum.notes()==1 && drum.result().kit.steps[1][0].enabled && !drum.result().kit.steps[6][0].enabled);
}
