int main(int argc,char** argv){setvbuf(stdout,nullptr,_IOLBF,0);char dir[]="/tmp/mk3-wave12-XXXXXX";CHECK(mkdtemp(dir));auto cwd=std::filesystem::current_path();std::filesystem::current_path(dir);unsigned failed=0;auto run=[&](const char* name,auto fn){const char* only=argc>1?argv[1]:std::getenv("MGX_WAVE12_ONLY");if(only && !std::strstr(name,only))return;printf("START %s\n",name);try{fn();printf("PASS %s\n",name);}catch(const std::exception& e){++failed;printf("FAIL %s: %s\n",name,e.what());}};run("21 scales and unique octave pads",scales);run("13 shapes x 4 inversions exact playback/record/release",shapes);run("eight-note record/save/read/play and old format rejection",eight);run("GM exact/fold/spill/drop/atomic Undo/live IO/codec",gm);run("SF2 bank128 mapped audio versus melodic bank",soundfont);run("workflow and six-theme screen captures",workflow);run("SMF eight-note import and GM export round trip",smf_files);run("SF2 native repeat and retrospective chord pitch intent",native_repeat_retro);run("scale chord quality names",scale_names);run("gapped chord editor identity and Undo",gapped_chord);std::filesystem::current_path(cwd);std::filesystem::remove_all(dir);return failed?1:0;}
